import logging
import os
import posixpath
import re

from taf.nms.netact.command import CommandBuilder
from taf.nms.netact.ssh_node import SshNode

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class OperationError(Exception):
    pass


class TroubleshootingTools:
    SYMPTOM_COLLECTOR = 'symptomcollector'

    def __init__(self, ssh_was_node: SshNode) -> None:
        self.ssh_was_node = ssh_was_node

    def get_supported_symptom_collector_components(self) -> list[str]:
        command = CommandBuilder(
            executable=self.SYMPTOM_COLLECTOR,
            flags=['--list-components']
        )

        with self.ssh_was_node as ssh:
            output = ssh.execute_command(command.text, ignore_stderr=True, ignore_rc=True).stdout
            return re.findall(r"\d+\)\s+(.+)\s", output)

    def collect_symptom_data_by_component(self,
                                          component: str,
                                          local_dir_path: str,
                                          log_all: bool = False,
                                          include_systeminfo: bool = False
                                          ) -> str:
        """
        Collect and download symptom data for a given component.

        :param str|list(str) component: A selected component (or a list thereof)
            such as ``software-manager``, ``mediation-nwi3``, etc.
        :param bool local_dir_path: A local directory to which collected files will be saved as ZIP
        :param bool log_all: Set to `True` to collect all the information, including big files such as heapdump
        :param bool include_systeminfo: Set to `True` to collect system information such as NetAct release version
        :return: Path to downloaded ZIP file
        :rtype: string
        """
        flags = []
        if include_systeminfo:
            flags.append('--systeminfo')
        command = CommandBuilder(
            executable=self.SYMPTOM_COLLECTOR,
            options={'--component': component,
                     '--log-level': 'all' if log_all else None},
            flags=flags
        )

        with self.ssh_was_node as ssh:
            output = ssh.execute_command(command.text, ignore_stderr=True, ignore_rc=True).stdout
            logger.debug(output)

            match = re.search(r"Logs directory\s+(.*)\s", output)
            if match:
                logs_dir_path = match.group(1)
                return self._zip_and_download_remote_directory(logs_dir_path, local_dir_path, ssh)
            raise OperationError("Downloading logs to the local host is not possible."
                                 "'Logs directory' was not provided in the output. ")

    @staticmethod
    def _zip_and_download_remote_directory(remote_dir_path: str,
                                           local_dir_path: str,
                                           ssh_connection: SshNode
                                           ) -> str:
        """
        For example using:
           remote_path = '/var/opt/nokia/oss/global/NSN-mhcf/omc/symptomcollector/20230524_114410_1726876405'
           local_path = '/home/ute/logs/'

        will ZIP `remote path` and save it locally as /home/ute/logs/symptomcollector_20230524_114410_1726876405.zip'
        """

        parent_dir_path = posixpath.dirname(remote_dir_path)
        dir_to_zip_name = posixpath.basename(remote_dir_path)
        zip_file_name = f'symptomcollector_{dir_to_zip_name}.zip'
        zip_file_path = posixpath.join('/tmp', zip_file_name)

        command = f'cd {parent_dir_path}; zip -r {zip_file_path} {dir_to_zip_name}'
        try:
            output = ssh_connection.execute_command(command, ignore_stderr=True, ignore_rc=True).stdout
            logger.debug(output)

            if not os.path.exists(local_dir_path):
                os.makedirs(local_dir_path)
            local_file_path = os.path.join(local_dir_path, zip_file_name)

            ssh_connection.get_file(zip_file_path, local_file_path)
            logger.debug(f'Saved file: {local_file_path}')
        finally:
            ssh_connection.execute_command(f'rm -f {zip_file_path}')

        return local_file_path
